/**
 * One-shot migration tool: freeze the DSH 0.1.1-rc.2 `@deepseek-ai/dsh-host-apiproxy`
 * wire vocabulary into `src/contract/`, the terminal bundle's own Host API
 * contract. DSH 0.2.x replaced that package with the Typert Remote assembly
 * (`@deepseek-ai/dsh-api-gateway` + per-domain `/remote` contributions), so the
 * vocabulary the terminal renders can no longer be imported from a live
 * dependency. `src/host/endpoints.ts` owns the mapping from this frozen
 * vocabulary onto the current Remote endpoints.
 *
 * Run once with `node scripts/vendor-contract.mjs` from a checkout whose
 * node_modules still carries `@deepseek-ai/dsh-host-apiproxy@0.1.1-rc.2`; the
 * generated sources are committed, and this script is not part of the build.
 */
import { mkdir, readFile, readdir, writeFile } from 'node:fs/promises'
import { dirname, join, resolve } from 'node:path'
import { fileURLToPath } from 'node:url'

const root = resolve(dirname(fileURLToPath(import.meta.url)), '..')
// The historical package is no longer part of the DSH tree, so the source may
// be pointed at an unpacked 0.1.1-rc.2 tarball:
//   mkdir -p /tmp/vendor-src && cd /tmp/vendor-src \
//     && npm pack @deepseek-ai/dsh-host-apiproxy@0.1.1-rc.2 && tar xzf *.tgz
const source = process.env.DSH_CONTRACT_SOURCE
  ?? join(root, 'node_modules/@deepseek-ai/dsh-host-apiproxy/lib/types')
const target = join(root, 'src/contract')

const HEADER = `/* Generated by scripts/vendor-contract.mjs from @deepseek-ai/dsh-host-apiproxy@0.1.1-rc.2 — do not edit by hand. */\n`

/** Drop zod-schema exports and imports; the frozen contract is type-only. */
function rewrite(text) {
  return text
    .replace(/^import \{ z \} from 'zod';\n/gm, '')
    .replace(/^import type \{ z[^}]*\} from 'zod';\n/gm, '')
    // DSH 0.2.x moved these two names; the frozen vocabulary keeps its own
    // shape and reads them from their current owners.
    .replace(/CallId/g, 'ToolCallId')
    .replace(/import type \{ JsonValue, SessionEvent, SessionId \} from '@deepseek-ai\/dsh-session\/types';\n/gm,
      "import type { JsonValue } from '@deepseek-ai/dsh-util-values';\nimport type { SessionEvent, SessionId } from '@deepseek-ai/dsh-session/types';\n")
    .replace(/^type ZodIssue = .*\n/gm, '')
    .replace(/^export \{ .*\} from '\.\/rpc\.schema\.ts';\n/gm, '')
    // Runtime values live in ./runtime.ts (hand-written); drop the body-less
    // declarations the .d.ts form carries.
    .replace(/^export declare function .*\n/gm, '')
    .replace(/^export declare const .*\n/gm, '')
    .replace(/^export function .*;\n/gm, '')
    .replace(/^export const .*;\n/gm, '')
    .replace(/^export \{ RpcId, transportError \} from '\.\/rpc\.ts';\n/gm, '')
    .replace(/^export \{ SESSION_SEARCH_RESULT_LIMIT, SESSION_SEARCH_SNIPPET_MAX_CODE_POINTS, \} from '\.\/session-search\.ts';\n/gm, '')
    .replace(/\n*\/\/# sourceMappingURL=.*$/m, '\n')
}

await mkdir(target, { recursive: true })
const apiSource = join(source, 'api')
const names = (await readdir(apiSource))
  .filter(name => name.endsWith('.d.ts') && !name.endsWith('.schema.d.ts'))
  .map(name => name.replace(/\.d\.ts$/u, ''))
  .filter(name => name !== 'index')

const ZOD_ISSUE = `\n/** Structural stand-in for the zod issue shape the frozen contract referenced. */\nexport interface ZodIssue {\n  code?: string\n  path?: (string | number)[]\n  message: string\n}\n`

for (const name of names) {
  const text = await readFile(join(apiSource, `${name}.d.ts`), 'utf8')
  let body = rewrite(text)
  if (body.includes('ZodIssue')) body = ZOD_ISSUE + body
  await writeFile(join(target, `${name}.ts`), HEADER + body)
}

// The consumer face (IApiClient) is the only part of fetch/client.d.ts this
// bundle uses; the abstract carrier classes stay out because the terminal owns
// its own transports.
const clientSource = await readFile(join(source, 'fetch/client.d.ts'), 'utf8')
const interfaceStart = clientSource.indexOf('export interface IApiClient {')
const interfaceEnd = clientSource.indexOf('\n}\n', interfaceStart)
if (interfaceStart < 0 || interfaceEnd < 0) throw new Error('IApiClient interface not found')
const clientText = `${HEADER}import type { ApiProxy, HostFrame, MuxFrame } from './index.ts';\nimport type { RequestPayload, ResponseValue } from './rpc-map.ts';\nimport type { ClientResponse, RpcReceipt, RpcRequest, RpcResponse } from './rpc.ts';\n\n${clientSource.slice(interfaceStart, interfaceEnd + 3)}\n/** Response entry for server requests; not a domain method. */\nexport type Respond = (message: ClientResponse, signal?: AbortSignal) => Promise<RpcReceipt>\n/** Mux stream opener; the terminal owns both transports. */\nexport type OpenMux = (payload: Parameters<ApiProxy['events']['mux']>[0]['payload'], signal: AbortSignal, onOpen?: () => void) => AsyncIterable<RpcRequest<MuxFrame>>\n/** Host stream opener. */\nexport type OpenHost = (payload: Parameters<ApiProxy['events']['host']>[0]['payload'], signal: AbortSignal, onOpen?: () => void) => AsyncIterable<RpcRequest<HostFrame>>\n`
await writeFile(join(target, 'client.ts'), clientText)

const indexPath = join(apiSource, 'index.d.ts')
const index = rewrite(await readFile(indexPath, 'utf8'))
// Load-bearing type-only imports: these packages augment SessionProjectionMap,
// which the frozen vocabulary only references. Without them the projection
// values the terminal reads (`title`, `goal`, `sessionStats`) are untyped.
const AUGMENTATIONS = `
import type {} from '@deepseek-ai/dsh-goal/types'
import type {} from '@deepseek-ai/dsh-session-stats/types'
import type {} from '@deepseek-ai/dsh-session-title/types'
`
await writeFile(join(target, 'index.ts'), HEADER + index
  + AUGMENTATIONS
  + "export type { IApiClient, OpenHost, OpenMux, Respond } from './client.ts';\n\n"
  + "export { RpcId, transportError, SESSION_SEARCH_RESULT_LIMIT, SESSION_SEARCH_SNIPPET_MAX_CODE_POINTS } from './runtime.ts';\n")
console.log(`vendored ${names.length + 2} contract modules into src/contract`)
